#!/usr/bin/env python3
from __future__ import annotations

import base64
import gzip
import hashlib
from pathlib import Path

TARGET = Path("scripts/freeze_japan_academy_imperial_section_adjudication_v1.py")
PAYLOAD_SHA256 = "884bdea208a5c8a82445933d27cea6b572e588accedd8797344099b54e26827c"
PAYLOAD_B64_GZIP = ""


def main() -> int:
    data = gzip.decompress(base64.b64decode(PAYLOAD_B64_GZIP))
    actual = hashlib.sha256(data).hexdigest()
    if actual != PAYLOAD_SHA256:
        raise RuntimeError(f"Embedded payload SHA mismatch: {actual}")
    if TARGET.exists():
        current = hashlib.sha256(TARGET.read_bytes()).hexdigest()
        if current == PAYLOAD_SHA256:
            print(f"ALREADY INSTALLED: {TARGET}")
            print(f"sha256={current}")
            return 0
        backup = TARGET.with_suffix(TARGET.suffix + ".pre_adjudication_v1.bak")
        if not backup.exists():
            backup.write_bytes(TARGET.read_bytes())
    TARGET.parent.mkdir(parents=True, exist_ok=True)
    TARGET.write_bytes(data)
    print(f"INSTALL OK: {TARGET}")
    print(f"sha256={actual}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
